19	    const char* name;
20	    switch (type & ~coVectorType) {
21	    case coNone: name = "none"; break;
22	    case coFloat: name = "float"; break;
23	    case coInt: name = "integer"; break;
24	    case coString: name = "string"; break;
25	    case coPercent: name = "percent"; break;
26	    case coFloatOrPercent: name = "float_or_percent"; break;
27	    case coPoint: name = "point"; break;
28	    case coPoint3: name = "point3"; break;
29	    case coBool: name = "boolean"; break;
30	    case coEnum: name = "enum"; break;
31	    case coPointsGroups - coVectorType: name = "point_groups"; break;
32	    case coIntsGroups - coVectorType: name = "integer_groups"; break;
33	    default: throw std::logic_error("Unknown Orca setting type");
34	    }
