82	inline bool has_scope_setting(const std::string& key, SettingsScope scope)
83	{
84	    const auto& keys = scope_options(scope);
85	    return print_config_def.get(key) && std::find(keys.begin(), keys.end(), key) != keys.end() &&
86	           (scope != SettingsScope::Object || object_setting(key));
